/**
 * Core constants for the Qoder Agent SDK.
 *
 * Hook events, exit reasons, timing constants, and version info.
 */
/**
 * Hook events supported by the public SDK hook registration API.
 */
export declare const HOOK_EVENTS: readonly ["PreToolUse", "PostToolUse", "PostToolUseFailure", "UserPromptSubmit", "SessionStart", "SessionEnd", "Stop", "SubagentStart", "SubagentStop", "PreCompact", "PostCompact", "CwdChanged", "InstructionsLoaded", "FileChanged", "PermissionRequest"];
/**
 * All supported exit reasons for session termination.
 */
export declare const EXIT_REASONS: readonly ["clear", "resume", "logout", "prompt_input_exit", "other", "bypass_permissions_disabled"];
/**
 * Grace period in milliseconds before sending SIGTERM after closing stdin.
 * Gives the CLI process time to flush and exit cleanly.
 */
export declare const CLOSE_GRACE_MS = 2000;
/**
 * Grace period in milliseconds before sending SIGKILL after SIGTERM.
 * If the process hasn't exited after SIGTERM within this window, force-kill it.
 */
export declare const KILL_GRACE_MS = 5000;
